<?php
function opsItemSnapshot($item){return ['item_name'=>$item['item_name'],'item_price'=>(float)$item['item_price'],'item_cost'=>(float)$item['item_cost'],'units_sold'=>(int)$item['units_sold'],'category'=>$item['category'],'details'=>$item['details']];}
function opsSame($a,$b){return hash('sha256',opsJson($a))===hash('sha256',opsJson($b));}
function opsWriteItem($pdo,$uid,$id,$snapshot){opsValidateCatalog($pdo,$uid,(int)$id,$snapshot['details']);opsExec($pdo,'UPDATE business_catalog SET item_name=?,item_price=?,item_cost=?,units_sold=?,category=? WHERE user_id=? AND id=?',[$snapshot['item_name'],$snapshot['item_price'],$snapshot['item_cost'],$snapshot['units_sold'],$snapshot['category'],$uid,$id]);saveCatalogDetails($pdo,$uid,$id,$snapshot['details']);}
function opsImportPreview($pdo,$uid,$d){
    $draft=opsGetRecord($pdo,$uid,(int)($d['draft_id']??0),'import_drafts');if(!empty($draft['data']['consumed']))throw new RuntimeException('Импорт уже сохранён');$kind=$draft['data']['target'];$rows=$d['rows']??[];if(!is_array($rows)||!count($rows)||count($rows)>500)throw new RuntimeException('Выберите от 1 до 500 строк');$mode=($d['mode']??'add')==='upsert'?'upsert':'add';$changes=[];$catalog=$kind==='catalog'?opsCatalog($pdo,$uid):[];$used=[];$type=businessProfile($pdo,$uid)['type'];
    foreach($rows as $raw){$clean=cleanImportRow($kind,$raw);if($kind!=='catalog'){$changes[]=['kind'=>$kind,'action'=>'add','after'=>$clean];continue;}$sku=opsText($raw['sku']??'',80);$matches=array_values(array_filter($catalog,fn($x)=>$sku?mb_strtolower($x['details']['sku']??'')===mb_strtolower($sku):mb_strtolower(trim($x['item_name']))===mb_strtolower(trim($clean['name']))));if(count($matches)>1)throw new RuntimeException('Неоднозначное совпадение: '.$clean['name'].'. Укажите уникальный артикул.');$found=$matches[0]??null;$unique=$sku?'sku:'.mb_strtolower($sku):'name:'.mb_strtolower(trim($clean['name']));if(isset($used[$unique]))throw new RuntimeException('В файле повторяется '.$clean['name']);$used[$unique]=true;
        if($found&&$mode==='add'){$changes[]=['kind'=>'catalog','action'=>'skip','id'=>(int)$found['id'],'name'=>$clean['name']];continue;}$before=$found?opsItemSnapshot($found):null;$meta=$before['details']??[];foreach(['sku','unit','description','aliases','availability','data_mode'] as $key)if(isset($raw[$key])&&$raw[$key]!=='')$meta[$key]=$raw[$key];$meta=catalogDetails($meta,$type);$after=['item_name'=>$clean['name'],'item_price'=>$clean['price'],'item_cost'=>$before&&!empty($d['prices_only'])?$before['item_cost']:$clean['cost'],'units_sold'=>$before&&!empty($d['prices_only'])?$before['units_sold']:$clean['quantity'],'category'=>$clean['category'],'details'=>$meta];$changes[]=['kind'=>'catalog','action'=>$found?'update':'add','id'=>$found?(int)$found['id']:null,'before'=>$before,'after'=>$after];}
    $record=['name'=>'Проверка импорта','draft_id'=>(int)$d['draft_id'],'kind'=>$kind,'mode'=>$mode,'changes'=>$changes,'state'=>'review','created_at'=>opsNow()];$id=opsRecord($pdo,$uid,'ops_import',$record);return ['id'=>$id]+$record;
}
function opsImportApply($pdo,$uid,$id){return opsTx($pdo,$uid,function()use($pdo,$uid,$id){$r=opsGetRecord($pdo,$uid,$id,'ops_import',true);$d=$r['data'];if($d['state']!=='review')throw new RuntimeException('Этот импорт уже применён');$source=opsGetRecord($pdo,$uid,$d['draft_id'],'import_drafts',true);if(!empty($source['data']['consumed']))throw new RuntimeException('Исходный импорт уже использован');$applied=[];$skipped=0;$current=opsCatalog($pdo,$uid);$names=[];$skus=[];foreach($current as $i){$names[mb_strtolower(trim($i['item_name']))]=true;if(!empty($i['details']['sku']))$skus[mb_strtolower($i['details']['sku'])]=true;}
    foreach($d['changes'] as $c){if($c['action']==='skip'){$skipped++;continue;}$kind=$c['kind'];if($kind==='catalog'){$after=$c['after'];if($c['action']==='update'){if(!opsSame(opsItemSnapshot(opsItem($pdo,$uid,$c['id'])),$c['before']))throw new RuntimeException('Каталог изменился после просмотра. Подготовьте импорт заново.');opsWriteItem($pdo,$uid,$c['id'],$after);$itemId=$c['id'];}else{$name=mb_strtolower(trim($after['item_name']));$sku=mb_strtolower($after['details']['sku']??'');if(isset($names[$name])||($sku&&isset($skus[$sku])))throw new RuntimeException('Одна из новых позиций уже появилась. Обновите просмотр.');opsExec($pdo,'INSERT INTO business_catalog(user_id,item_name,item_price,item_cost,units_sold,category) VALUES(?,?,?,?,?,?)',[$uid,$after['item_name'],$after['item_price'],$after['item_cost'],$after['units_sold'],$after['category']]);$itemId=(int)$pdo->lastInsertId();opsValidateCatalog($pdo,$uid,$itemId,$after['details']);saveCatalogDetails($pdo,$uid,$itemId,$after['details']);$names[$name]=true;if($sku)$skus[$sku]=true;}$c['id']=$itemId;}else{if($kind==='knowledge'&&count(opsRecords($pdo,$uid,'knowledge'))>=500)throw new RuntimeException('Лимит базы знаний — 500 записей');$c['id']=opsRecord($pdo,$uid,$kind,$c['after']);}$applied[]=$c;}
    $d['changes']=$applied;$d['state']='applied';$d['applied_at']=opsNow();opsPutRecord($pdo,$uid,$id,$d);$source['data']['consumed']=true;opsPutRecord($pdo,$uid,$source['id'],$source['data']);opsExec($pdo,'UPDATE aulieata_records SET archived=1 WHERE user_id=? AND id=?',[$uid,$source['id']]);$audit=opsAudit($pdo,$uid,'import',$id,['changes'=>$applied]);return ['ok'=>true,'count'=>count($applied),'skipped'=>$skipped,'audit_id'=>$audit];});}
function opsHasOrderItem($pdo,$uid,$id){foreach(opsAll($pdo,"SELECT payload FROM ops_orders WHERE user_id=? AND status NOT IN ('cancelled','refunded')",[$uid]) as $r)foreach(json_decode($r['payload'],true)['items']??[] as $line)if((int)$line['item_id']===$id)return true;return false;}
function opsUndo($pdo,$uid,$auditId){return opsTx($pdo,$uid,function()use($pdo,$uid,$auditId){$a=opsOne($pdo,'SELECT * FROM ops_audit WHERE user_id=? AND id=? FOR UPDATE',[$uid,$auditId]);if(!$a||$a['undone'])throw new RuntimeException('Действие не найдено или уже отменено');$d=json_decode($a['payload'],true);$changes=[];if(in_array($a['kind'],['import','owner_plan']))$changes=$d['changes']??[];elseif($a['kind']==='catalog_edit')$changes=[['kind'=>'catalog','action'=>empty($d['before'])?'add':'update','id'=>(int)$a['target_id'],'before'=>$d['before'],'after'=>$d['after']]];else throw new RuntimeException('Для этого события автоматическая отмена недоступна');
    foreach(array_reverse($changes) as $c){if($c['kind']==='catalog'){if(!opsSame(opsItemSnapshot(opsItem($pdo,$uid,(int)$c['id'])),$c['after']))throw new RuntimeException('После этого действия карточка менялась. Автоматическая отмена остановлена.');if(opsHasOrderItem($pdo,$uid,(int)$c['id']))throw new RuntimeException('Позиция уже связана с заказами. Измените её вручную.');if(!empty($c['before']))opsWriteItem($pdo,$uid,$c['id'],$c['before']);else opsExec($pdo,'INSERT INTO aulieata_catalog_status(user_id,item_id,archived) VALUES(?,?,1) ON DUPLICATE KEY UPDATE archived=1',[$uid,$c['id']]);}else{$r=opsGetRecord($pdo,$uid,$c['id'],$c['kind'],true);if(!opsSame($r['data'],$c['after']))throw new RuntimeException('Запись менялась после создания. Отмена остановлена.');if($c['kind']==='stock_batches'){if(opsOne($pdo,'SELECT order_id FROM ops_reservations WHERE user_id=? AND batch_id=? LIMIT 1',[$uid,$c['id']]))throw new RuntimeException('Партия уже использовалась в заказе');}opsExec($pdo,'UPDATE aulieata_records SET archived=1 WHERE user_id=? AND id=?',[$uid,$c['id']]);}}
    opsExec($pdo,'UPDATE ops_audit SET undone=1 WHERE user_id=? AND id=?',[$uid,$auditId]);if($a['kind']==='import'){$r=opsGetRecord($pdo,$uid,$a['target_id'],'ops_import');$r['data']['state']='undone';opsPutRecord($pdo,$uid,$r['id'],$r['data']);}opsAudit($pdo,$uid,'undo',$auditId,['changes'=>count($changes)]);return ['ok'=>true];});}
